1	// Offline route resolution: match a request against configured route prefixes
2	// and join the remainder onto the upstream base path without any network I/O.
3	package contractsentinel
4	
5	import (
6		"bytes"
7		"encoding/json"
8		"fmt"
9		"net/url"
10		"sort"
11		"strings"
12	)
13	
14	// Route is one configured route: an id, accepted methods, a path prefix and
15	// the upstream URL requests on that route are forwarded to. An optional
16	// queryTransforms list rewrites the request query string after the route has
17	// been selected.
18	type Route struct {
19		ID              string            `json:"id"`
20		Methods         []string          `json:"methods"`
21		PathPrefix      string            `json:"pathPrefix"`
22		Upstream        string            `json:"upstream"`
23		QueryTransforms []*QueryTransform `json:"-"`
24	
25		// queryTransformsRaw holds the undecoded queryTransforms value between
26		// Route.UnmarshalJSON and Config.UnmarshalJSON, which validates it once
27		// the route's position in its own config is known.
28		queryTransformsRaw json.RawMessage
29	}
30	
31	// QueryTransform is one rule in a route's queryTransforms array: op is
32	// "set", "remove" or "rename"; name is matched against decoded parameter
33	// names, value (set only) is used literally, and to (rename only) is the
34	// literal replacement name.
35	type QueryTransform struct {
36		Op    string `json:"op"`
37		Name  string `json:"name"`
38		Value string `json:"value"`
39		To    string `json:"to"`
40	}
41	
42	// routeJSON mirrors Route, keeping queryTransforms as raw JSON so null,
43	// wrong types and malformed rules can be reported with the route's location
44	// instead of as a generic decode error.
45	type routeJSON struct {
46		ID              string          `json:"id"`
47		Methods         []string        `json:"methods"`
48		PathPrefix      string          `json:"pathPrefix"`
49		Upstream        string          `json:"upstream"`
50		QueryTransforms json.RawMessage `json:"queryTransforms"`
51	}
52	
53	// UnmarshalJSON decodes a route object and keeps queryTransforms raw; the
54	// enclosing Config.UnmarshalJSON validates it with the route's 1-based
55	// position in that config's routes array.
56	func (route *Route) UnmarshalJSON(data []byte) error {
57		var rj routeJSON
58		if err := json.Unmarshal(data, &rj); err != nil {
59			return err
60		}
61		route.ID = rj.ID
62		route.Methods = rj.Methods
63		route.PathPrefix = rj.PathPrefix
64		route.Upstream = rj.Upstream
65		route.QueryTransforms = nil
66		route.queryTransformsRaw = rj.QueryTransforms
67		return nil
68	}
69	
70	// parseQueryTransforms decodes and validates the raw queryTransforms array
71	// of one route. loc identifies the route; rule errors additionally carry a
72	// 1-based rule index.
73	func parseQueryTransforms(raw json.RawMessage, loc, id string) ([]*QueryTransform, *Failure) {
74		body := strings.TrimSpace(string(raw))
75		if body == "null" {
76			return nil, failuref("invalid_config", "%s: queryTransforms must not be null", routeLabel(loc, id))
77		}
78		var elems []json.RawMessage
79		if err := json.Unmarshal([]byte(body), &elems); err != nil {
80			return nil, failuref("invalid_config", "%s: queryTransforms must be an array", routeLabel(loc, id))
81		}
82		transforms := make([]*QueryTransform, 0, len(elems))
83		for i, elem := range elems {
84			ruleLoc := fmt.Sprintf("%s, queryTransforms rule %d", routeLabel(loc, id), i+1)
85			if string(bytes.TrimSpace(elem)) == "null" {
86				return nil, failuref("invalid_config", "%s: rule must not be null", ruleLoc)
87			}
88			var fields map[string]json.RawMessage
89			if err := json.Unmarshal(elem, &fields); err != nil {
90				return nil, failuref("invalid_config", "%s: rule must be a JSON object", ruleLoc)
91			}
92	
93			qt := &QueryTransform{}
94			opRaw, ok := fields["op"]
95			switch {
96			case !ok:
97				return nil, failuref("invalid_config", "%s: op is required", ruleLoc)
98			case !jsonString(opRaw, &qt.Op):
99				return nil, failuref("invalid_config", "%s: op must be a string", ruleLoc)
100			case qt.Op != "set" && qt.Op != "remove" && qt.Op != "rename":
101				return nil, failuref("invalid_config", "%s: unknown op %q (only set, remove and rename are supported)", ruleLoc, qt.Op)
102			}
103	
104			nameRaw, ok := fields["name"]
105			switch {
106			case !ok:
107				return nil, failuref("invalid_config", "%s: name is required", ruleLoc)
108			case !jsonString(nameRaw, &qt.Name):
109				return nil, failuref("invalid_config", "%s: name must be a non-empty string", ruleLoc)
110			case qt.Name == "":
111				return nil, failuref("invalid_config", "%s: name must be a non-empty string", ruleLoc)
112			}
113	
114			valueRaw, hasValue := fields["value"]
115			toRaw, hasTo := fields["to"]
116			switch qt.Op {
117			case "set":
118				if !hasValue {
119					return nil, failuref("invalid_config", "%s: set requires a string value", ruleLoc)
120				}
121				if !jsonString(valueRaw, &qt.Value) {
122					return nil, failuref("invalid_config", "%s: value must be a string", ruleLoc)
123				}
124			case "remove":
125				if hasValue {
126					return nil, failuref("invalid_config", "%s: remove must not include a value", ruleLoc)
127				}
128			case "rename":
129				if hasValue {
130					return nil, failuref("invalid_config", "%s: rename must not include a value", ruleLoc)
131				}
132				switch {
133				case !hasTo:
134					return nil, failuref("invalid_config", "%s: rename requires a non-empty string to", ruleLoc)
135				case !jsonString(toRaw, &qt.To):
136					return nil, failuref("invalid_config", "%s: to must be a non-empty string", ruleLoc)
137				case qt.To == "":
138					return nil, failuref("invalid_config", "%s: to must be a non-empty string", ruleLoc)
139				}
140			}
141			transforms = append(transforms, qt)
142		}
143		return transforms, nil
144	}
145	
146	// jsonString decodes raw into s and reports whether raw is a JSON string
147	// (null, numbers, objects and arrays fail).
148	func jsonString(raw json.RawMessage, s *string) bool {
149		if len(raw) == 0 || raw[0] != '"' {
150			return false
151		}
152		return json.Unmarshal(raw, s) == nil
153	}
154	
155	// routeLabel renders the human-readable route location, adding the id when
156	// the configuration supplied one.
157	func routeLabel(loc, id string) string {
158		if id != "" {
159			return fmt.Sprintf("%s (id %q)", loc, id)
160		}
161		return loc
162	}
163	
164	// Config is the resolve configuration: a flat array of routes.
165	type Config struct {
166		Routes []Route `json:"routes"`
167	}
168	
169	// UnmarshalJSON decodes the routes array and validates each route's
170	// queryTransforms against that route's position in this config. The position
171	// comes from the array being decoded here, so configs parsed concurrently or
172	// interleaved in the same process cannot shift each other's route numbering.
173	func (cfg *Config) UnmarshalJSON(data []byte) error {
174		var raw struct {
175			Routes []Route `json:"routes"`
176		}
177		if err := json.Unmarshal(data, &raw); err != nil {
178			return err
179		}
180		cfg.Routes = raw.Routes
181		for i := range cfg.Routes {
182			route := &cfg.Routes[i]
183			if len(route.queryTransformsRaw) == 0 {
184				continue // field absent
185			}
186			loc := fmt.Sprintf("route %d", i+1)
187			transforms, f := parseQueryTransforms(route.queryTransformsRaw, loc, route.ID)
188			if f != nil {
189				return f
190			}
191			route.QueryTransforms = transforms
192			route.queryTransformsRaw = nil
193		}
194		return nil
195	}
196	
197	// Request is one resolution request: an HTTP method and a request target
198	// (path with an optional raw query string).
199	type Request struct {
200		Method string `json:"method"`
201		Target string `json:"target"`
202	}
203	
204	// Resolution is the successful result of matching a request.
205	type Resolution struct {
206		RouteID     string `json:"routeId"`
207		UpstreamURL string `json:"upstreamURL"`
208	}
209	
210	// Failure carries a stable machine-readable code and a human-readable reason.
211	type Failure struct {
212		Code       string   `json:"code"`
213		Reason     string   `json:"reason"`
214		Candidates []string `json:"candidates,omitempty"`
215	}
216	
217	func (f *Failure) Error() string { return f.Code + ": " + f.Reason }
218	
219	func failuref(code, format string, args ...any) *Failure {
220		return &Failure{Code: code, Reason: fmt.Sprintf(format, args...)}
221	}
222	
223	// ParseConfig parses and fully validates the route configuration.
224	func ParseConfig(data []byte) (*Config, *Failure) {
225		var cfg Config
226		if err := json.Unmarshal(data, &cfg); err != nil {
227			if f, ok := err.(*Failure); ok {
228				return nil, f
229			}
230			return nil, failuref("invalid_config", "config is not valid JSON: %v", err)
231		}
232		if f := cfg.validate(); f != nil {
233			return nil, f
234		}
235		return &cfg, nil
236	}
237	
238	func (cfg *Config) validate() *Failure {
239		seenIDs := make(map[string]int, len(cfg.Routes))
240		for i := range cfg.Routes {
241			route := &cfg.Routes[i]
242			loc := fmt.Sprintf("route %d", i+1)
243			if route.ID == "" {
244				return failuref("invalid_config", "%s: id must be non-empty", loc)
245			}
246			if first, ok := seenIDs[route.ID]; ok {
247				return failuref("invalid_config", "%s: duplicate id %q (already used by route %d)", loc, route.ID, first)
248			}
249			seenIDs[route.ID] = i + 1
250	
251			if len(route.Methods) == 0 {
252				return failuref("invalid_config", "%s (id %q): methods must be a non-empty array", loc, route.ID)
253			}
254			for _, method := range route.Methods {
255				switch {
256				case method == "":
257					return failuref("invalid_config", "%s (id %q): methods must not contain empty entries", loc, route.ID)
258				case method == "*":
259					// Wildcard matching any legal method.
260				case !isToken(method):
261					return failuref("invalid_config", "%s (id %q): invalid method %q", loc, route.ID, method)
262				}
263			}
264	
265			if f := validatePrefix(route.PathPrefix, loc, route.ID); f != nil {
266				return f
267			}
268			if f := validateUpstream(route.Upstream, loc, route.ID); f != nil {
269				return f
270			}
271		}
272		return nil
273	}
274	
275	func validatePrefix(prefix, loc, id string) *Failure {
276		switch {
277		case prefix == "" || prefix[0] != '/':
278			return failuref("invalid_config", "%s (id %q): pathPrefix must start with /", loc, id)
279		case prefix != "/" && strings.HasSuffix(prefix, "/"):
280			return failuref("invalid_config", "%s (id %q): pathPrefix must not end with / except for root", loc, id)
281		case strings.ContainsAny(prefix, "?#"):
282			return failuref("invalid_config", "%s (id %q): pathPrefix must not contain a query string or fragment", loc, id)
283		case !validPercentEscapes(prefix):
284			return failuref("invalid_config", "%s (id %q): pathPrefix contains an invalid percent escape", loc, id)
285		}
286		return nil
287	}
288	
289	func validateUpstream(raw, loc, id string) *Failure {
290		if strings.ContainsAny(raw, "?#") {
291			return failuref("invalid_config", "%s (id %q): upstream must not contain a query string or fragment", loc, id)
292		}
293		u, err := url.Parse(raw)
294		if err != nil {
295			return failuref("invalid_config", "%s (id %q): upstream is not a valid URL: %v", loc, id, err)
296		}
297		if u.Scheme != "http" && u.Scheme != "https" {
298			return failuref("invalid_config", "%s (id %q): upstream must be an absolute http or https URL", loc, id)
299		}
300		if u.Host == "" {
301			return failuref("invalid_config", "%s (id %q): upstream must include a host", loc, id)
302		}
303		return nil
304	}
305	
306	// ParseRequest parses and validates one JSON request.
307	func ParseRequest(data []byte) (*Request, *Failure) {
308		var req Request
309		if err := json.Unmarshal(data, &req); err != nil {
310			return nil, failuref("invalid_request", "request is not valid JSON: %v", err)
311		}
312		switch {
313		case req.Method == "":
314			return nil, failuref("invalid_request", "method is required")
315		case !isToken(req.Method):
316			return nil, failuref("invalid_request", "method %q is not a legal HTTP method", req.Method)
317		}
318		switch {
319		case req.Target == "" || req.Target[0] != '/':
320			return nil, failuref("invalid_request", "target must start with /")
321		case strings.Contains(req.Target, "#"):
322			return nil, failuref("invalid_request", "target must not contain a fragment")
323		case !validPercentEscapes(req.Target):
324			return nil, failuref("invalid_request", "target contains an invalid percent escape")
325		}
326		return &req, nil
327	}
328	
329	// Resolve matches a validated request against a validated configuration and
330	// computes the upstream URL. Failure codes are route_not_found and
331	// route_conflict.
332	func Resolve(cfg *Config, req *Request) (*Resolution, *Failure) {
333		path := req.Target
334		if i := strings.IndexByte(path, '?'); i >= 0 {
335			path = path[:i]
336		}
337	
338		type candidate struct {
339			route    *Route
340			concrete bool
341		}
342		var matched []candidate
343		for i := range cfg.Routes {
344			route := &cfg.Routes[i]
345			concrete, wildcard := methodMatch(route.Methods, req.Method)
346			if !concrete && !wildcard {
347				continue
348			}
349			if !prefixMatch(route.PathPrefix, path) {
350				continue
351			}
352			matched = append(matched, candidate{route, concrete})
353		}
354		if len(matched) == 0 {
355			return nil, failuref("route_not_found", "no route matches %s %s", req.Method, path)
356		}
357	
358		// Longest prefix wins.
359		bestLen := 0
360		for _, c := range matched {
361			if n := len(c.route.PathPrefix); n > bestLen {
362				bestLen = n
363			}
364		}
365		winners := matched[:0]
366		for _, c := range matched {
367			if len(c.route.PathPrefix) == bestLen {
368				winners = append(winners, c)
369			}
370		}
371	
372		// Among equal prefixes a concrete method beats the wildcard.
373		var concrete []candidate
374		for _, c := range winners {
375			if c.concrete {
376				concrete = append(concrete, c)
377			}
378		}
379		if len(concrete) > 0 {
380			winners = concrete
381		}
382		if len(winners) > 1 {
383			ids := make([]string, 0, len(winners))
384			for _, c := range winners {
385				ids = append(ids, c.route.ID)
386			}
387			sort.Strings(ids)
388			f := failuref("route_conflict", "multiple routes match %s %s", req.Method, path)
389			f.Candidates = ids
390			return nil, f
391		}
392	
393		upstreamURL, f := joinUpstream(winners[0].route, path, req.Target)
394		if f != nil {
395			return nil, f
396		}
397		return &Resolution{RouteID: winners[0].route.ID, UpstreamURL: upstreamURL}, nil
398	}
399	
400	// methodMatch reports whether the method list matches the request method
401	// concretely (an exact, case-sensitive entry) or via the "*" wildcard.
402	func methodMatch(methods []string, method string) (concrete, wildcard bool) {
403		for _, m := range methods {
404			switch {
405			case m == "*":
406				wildcard = true
407			case m == method:
408				concrete = true
409			}
410		}
411		return concrete, wildcard
412	}
413	
414	// prefixMatch matches raw encoded paths on segment boundaries: "%2F" is never
415	// treated as a separator and the root prefix matches every origin-path.
416	func prefixMatch(prefix, path string) bool {
417		if prefix == "/" {
418			return true
419		}
420		if path == prefix {
421			return true
422		}
423		return strings.HasPrefix(path, prefix) && path[len(prefix)] == '/'
424	}
425	
426	// joinUpstream strips the route prefix from the request path and joins the
427	// remainder onto the upstream base path with exactly one slash at the
428	// junction. The base path is carried over byte for byte: joining never
429	// re-encodes, reorders or drops anything outside that junction. The raw
430	// query is preserved verbatim unless the route defines queryTransforms, in
431	// which case they rewrite it after route selection.
432	func joinUpstream(route *Route, path, target string) (string, *Failure) {
433		if _, err := url.Parse(route.Upstream); err != nil {
434			// Config validation already rejected this.
435			return "", failuref("invalid_config", "route %q has an invalid upstream: %v", route.ID, err)
436		}
437	
438		var remainder string
439		switch {
440		case route.PathPrefix == "/":
441			// Root keeps the whole following path; "/" itself has an empty remainder.
442			if path != "/" {
443				remainder = path
444			}
445		default:
446			remainder = path[len(route.PathPrefix):] // "" or "/...", boundary is a literal slash
447		}
448	
449		// Slice the validated upstream raw so nothing outside the junction is
450		// normalized or re-escaped (scheme://[userinfo@]host[/base-path]).
451		schemeEnd := strings.Index(route.Upstream, "://")
452		tail := route.Upstream[schemeEnd+3:]
453		hostPart, basePath := tail, ""
454		if i := strings.IndexByte(tail, '/'); i >= 0 {
455			hostPart, basePath = tail[:i], tail[i:]
456		}
457		joined := strings.TrimSuffix(basePath, "/")
458		if remainder == "" {
459			joined += "/" // the junction slash is kept even with no remaining path
460		} else {
461			joined += remainder
462		}
463	
464		result := route.Upstream[:schemeEnd+3] + hostPart + joined
465		query, f := applyQueryTransforms(route.QueryTransforms, target)
466		if f != nil {
467			return "", f
468		}
469		return result + query, nil
470	}
471	
472	// isToken reports whether s is an RFC 7230 token, i.e. a legal HTTP method.
473	func isToken(s string) bool {
474		if s == "" {
475			return false
476		}
477		for i := 0; i < len(s); i++ {
478			if !isTokenChar(s[i]) {
479				return false
480			}
481		}
482		return true
483	}
484	
485	func isTokenChar(c byte) bool {
486		switch {
487		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
488			return true
489		}
490		switch c {
491		case '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^', '_', '`', '|', '~':
492			return true
493		}
494		return false
495	}
496	
497	// validPercentEscapes checks that every "%' is followed by two hex digits.
498	// Matching and joining stay on raw strings, but malformed escapes are rejected
499	// up front for both prefixes and request targets.
500	func validPercentEscapes(s string) bool {
501		for i := 0; i < len(s); i++ {
502			if s[i] != '%' {
503				continue
504			}
505			if i+2 >= len(s) || !isHex(s[i+1]) || !isHex(s[i+2]) {
506				return false
507			}
508			i += 2
509		}
510		return true
511	}
512	
513	func isHex(c byte) bool {
514		switch {
515		case c >= '0' && c <= '9', c >= 'a' && c <= 'f', c >= 'A' && c <= 'F':
516			return true
517		}
518		return false
519	}
